function dependencyCheck(items){const visit=(id,path=[])=>{if(path.includes(id))throw Error('前置关系不能循环');ref(items,id,'前置项目').prerequisiteIds.forEach(k=>visit(k,[...path,id]))};items.forEach(x=>visit(x.id))}
