painters['learning-progress']=s=>{const list=resources(s),visible=list.filter(x=>(!s.filter||learningRecord(s,x.id).status===s.filter)&&matches(s,x.title,x.chapterTitle));const selected=visible.find(x=>x.id===s.selected)||visible[0];s.selected=selected?.id;const total=list.length,complete=list.filter(x=>learningRecord(s,x.id).status==='completed').length;return metric([[complete+' / '+total,'已明确完成资源'],[total?round(complete/total*100)+'%':'—','完成比例'],[s.p.completion==='manual'?'手动确认':s.p.threshold+'% 后确认','完成规则']])+toolbar(s,select('学习状态','filter',[{id:'',label:'全部状态'},...Object.entries(learningLabels).map(([id,label])=>({id,label}))],s.filter||''))+`<div class="en-split"><nav class="en-step-nav" aria-label="章节资源">${visible.map(x=>b(x.chapterTitle+' / '+x.title+' · '+learningLabels[learningRecord(s,x.id).status],'learning-select',x.id,`aria-current="${x.id===selected?.id?'step':'false'}"`)).join('')||empty('没有符合条件的资源')}</nav><section>${selected?learningDetail(s,selected):empty('可传入章节和资源目录。')}</section></div>`+foot(s)};
