actions['learning-progress']=(s,a,id,button)=>{if(a==='learning-select'){s.selected=id;draw(s);return}const x=resources(s).find(y=>y.id===id);if(!x)return;const r=learningRecord(s,id),reason=learningBlocked(s,x);if(a==='learning-resume'){if(reason){fail(s,reason);return}emit(s,'action','learning-locate',{resourceId:id,position:r.position,type:x.type,locator:x.locator||null});s.message='已请求定位到当前记录位置，尚未改变学习记录。';draw(s);return}if(reason||x.locked)return;if(a==='learning-reset'&&s.p.allowReset)confirm(s,button,'重置学习记录？','将清除当前资源的本地进度；业务确认后生效。',d=>request(s,a,{resourceId:id,previous:clone(r)},()=>{s.value.records[id]={position:0,status:'not-started',history:[...(r.history||[]),{at:now(s),action:'重置',position:0}]};delete s.drafts['position:'+id]},d));if(teacher(s)||r.status==='completed')return;if(a==='learning-record'){const position=numeric(s.drafts['position:'+id]??r.position,'学习位置',{max:x.total});if(!Number.isInteger(position)){fail(s,'学习位置需为整数');return}request(s,a,{resourceId:id,position,recordedAt:now(s)},payload=>{s.value.records[id]={...r,position:payload.position,status:'in-progress',lastVisitedAt:payload.recordedAt,history:[...(r.history||[]),{at:payload.recordedAt,action:'记录进度',position:payload.position}]};delete s.drafts['position:'+id]})}if(a==='learning-complete'){if(r.status==='not-started'){fail(s,'请先记录实际学习进度');return}if(s.p.completion==='threshold'&&r.position/x.total*100<s.p.threshold){fail(s,'已确认学习记录尚未达到完成阈值；请先记录进度');return}confirm(s,button,'确认完成此资源？','按当前完成规则确认，不自动判断掌握程度。',d=>request(s,a,{resourceId:id,position:r.position},()=>{s.value.records[id]={...r,status:'completed',completedAt:now(s),history:[...(r.history||[]),{at:now(s),action:'确认完成',position:r.position}]}},d))}};
