function resourceVersionDetail(s,r,v){const usable=resourceUsable(s,v),compare=r.versions.find(x=>x.id===s.compareVersion),status=v.status==='available'&&!usable?'expired':v.status;return `<p>${badge(versionLabels[status],usable?'success':status==='draft'?'neutral':'warning')} · ${E(v.createdAt||'未提供创建时间')}</p>${v.note?`<p>版本说明：${E(v.note)}</p>`:''}${v.reason?`<p class="edu-warning">${E(v.reason)}</p>`:''}${usable||teacher(s)?`<pre class="en-resource-text">${E(v.content||'未提供可对比的文本正文')}</pre>${v.url?`<p>资源地址：${E(v.url)}</p>`:''}`:empty('当前版本不可用，内容与引用入口已锁定。')}<div class="v-row">${b('引用此版本','resource-cite',v.id,attr(s)+(!usable?' disabled':''))}${usable&&v.url?b('请求打开资源','resource-open',v.id):''}${teacher(s)&&v.status==='draft'?b('编辑草稿','version-edit',v.id,attr(s))+b('发布版本','version-publish',v.id,attr(s)):''}${teacher(s)&&v.status==='available'?b('设为不可用','version-withdraw',v.id,attr(s)+' data-tone="danger"'):''}</div>${r.versions.length>1?`<div class="en-compare">${select('与其他版本对照','resource-compare',[{id:'',label:'选择另一个版本'},...r.versions.filter(x=>x.id!==v.id).map(x=>({id:x.id,label:'v'+x.number+' · '+versionLabels[x.status]}))],compare?.id||'')}${compare?resourceDiff(s,v,compare):''}</div>`:''}`}
