function resourceDiff(s,a,b){if(!teacher(s)&&(!resourceUsable(s,a)||!resourceUsable(s,b)))return empty('不可用版本不提供正文对照。');const lines=diffLines(a.content,b.content);return `<p class="v-caption">v${a.number} 与 v${b.number} · 按文本行对照，${lines.filter(x=>x.changed).length} 行不同；文档附件需业务提供可比文本。</p><div class="en-diff">${lines.map(l=>`<div data-changed="${l.changed}"><span>${l.line}</span><pre>${E(l.left)}</pre><pre>${E(l.right)}</pre></div>`).join('')}</div>`}
function editVersion(s,button,r,v=null){if(!teacher(s)||r?.locked||v&&v.status!=='draft')return;const body=(r?'':input('资源名称','title','','text','maxlength="160"')+select('资源类型','type',[{id:'text',label:'文本资料'},{id:'document',label:'文档引用'},{id:'link',label:'链接资源'}],'text'))+area('正文或可对比文本','content',v?.content||'','maxlength="30000"')+input('资源链接（可选）','url',v?.url||'','url')+area('版本说明','note',v?.note||'','maxlength="1000"')+input('过期时间（可选）','expiresAt',v?.expiresAt?.slice(0,16)||'','datetime-local');modal(s,button,v?'编辑资源草稿':r?'创建下一版本':'新增资源与首个版本',body,(values,d)=>{if(values.url&&!safeURL(values.url))throw Error('请使用http(s)或相对资源地址');if(values.expiresAt&&(!Number.isFinite(date(values.expiresAt))||date(values.expiresAt)<=timestamp(s)))throw Error('过期时间需为有效的未来时间');const resource=r||{id:uid('resource'),title:required(values.title,'资源名称'),type:values.type,versions:[]};const version={id:v?.id||uid('version'),number:v?.number||Math.max(0,...resource.versions.map(x=>x.number))+1,status:'draft',content:values.content,url:values.url,note:values.note,expiresAt:values.expiresAt||null,createdAt:v?.createdAt||now(s)};request(s,'version-save',{resourceId:resource.id,version,...(!r?{resource:{...resource,versions:[]}}:{})},payload=>{let current=s.value.resources.find(x=>x.id===resource.id);if(!current){current=resource;s.value.resources.push(current)}const at=current.versions.findIndex(x=>x.id===version.id);if(at<0)current.versions.push(payload.version);else current.versions[at]=payload.version;s.selectedResource=current.id;s.selectedVersion=version.id},d)})}
actions['resource-version']=(s,a,id,button)=>{if(a==='resource-select'){s.selectedResource=id;s.selectedVersion=null;s.compareVersion=null;draw(s);return}if(a==='resource-add'){editVersion(s,button);return}const r=selectedResource(s);if(!r)return;if(a==='version-add'){editVersion(s,button,r);return}const v=r.versions.find(x=>x.id===id);if(a==='citation-remove'){const c=s.value.citations.find(x=>x.id===id);if(c)confirm(s,button,'移除引用快照？','仅移除此处引用，不删除源资源或其他版本。',d=>request(s,a,{citationId:id},()=>s.value.citations=s.value.citations.filter(x=>x.id!==id),d));return}if(!v)return;if(a==='resource-open'&&resourceUsable(s,v)&&safeURL(v.url)){emit(s,'action','resource-open',{resourceId:r.id,versionId:v.id,url:v.url});return}if(a==='resource-cite'){if(!resourceUsable(s,v)){fail(s,'此版本已不可用或过期，不能新增引用');return}if(s.value.citations.some(c=>c.resourceId===r.id&&c.versionId===id)){fail(s,'当前版本已引用，不重复添加');return}const snapshot={id:uid('citation'),resourceId:r.id,versionId:id,versionNumber:v.number,title:r.title,type:r.type,content:v.content||'',url:v.url||null,referencedAt:now(s)};request(s,a,{snapshot},payload=>s.value.citations.push(payload.snapshot));return}if(!teacher(s)||r.locked)return;if(a==='version-edit')editVersion(s,button,r,v);if(a==='version-publish'&&v.status==='draft'){if(!text(v.content).trim()&&!v.url){fail(s,'发布前需提供正文或有效资源地址');return}if(r.type==='link'&&!safeURL(v.url)){fail(s,'链接资源需要有效地址');return}if(v.expiresAt&&date(v.expiresAt)<=timestamp(s)){fail(s,'版本已过期，请先修改过期时间');return}confirm(s,button,'发布此资源版本？','已发布版本正文不可原地改写；后续修改需创建新版本。',d=>request(s,a,{resourceId:r.id,versionId:id,number:v.number},()=>{v.status='available';v.publishedAt=now(s)},d))}if(a==='version-withdraw'&&v.status==='available')modal(s,button,'将资源版本设为不可用',area('不可用原因','reason','','maxlength="1000"'),(value,d)=>{required(value.reason,'不可用原因');request(s,a,{resourceId:r.id,versionId:id,reason:value.reason.trim()},payload=>{v.status='unavailable';v.reason=payload.reason},d)},{danger:true})};
const questionTypes={single:'单选',multiple:'多选',rating:'量表',boolean:'是非',text:'文本'};
function currentSurvey(s){return {...s.p,questions:s.value.questions,status:s.value.status}}
function surveyClosedReason(s){if(s.value.status!=='open')return s.value.status==='draft'?'问卷尚未开放':'问卷已关闭';if(s.p.startsAt&&timestamp(s)<date(s.p.startsAt))return '问卷尚未到开始时间';if(s.p.endsAt&&timestamp(s)>=date(s.p.endsAt))return '问卷已截止';if(s.value.submitted)return '本次答卷已提交';return ''}
